import unittest

from solution import find_record


class SingleUseRecords:
    def __init__(self, records):
        self.records = records
        self.iterations = 0

    def __iter__(self):
        self.iterations += 1
        if self.iterations > 1:
            raise AssertionError("records iterable consumed more than once")
        return iter(self.records)


class FindRecordTests(unittest.TestCase):
    def test_matches_first_normalized_name(self):
        records = [
            {"name": " Other ", "id": 0},
            {"name": "  Straße ", "id": 1},
            {"name": "STRASSE", "id": 2},
        ]
        self.assertEqual(find_record(records, " strasse "), records[1])

    def test_returns_deep_copy(self):
        records = [
            {
                "name": "Ada",
                "profile": {"skills": ["Python", {"level": 5}]},
            }
        ]
        result = find_record(records, "ada")
        self.assertEqual(result, records[0])
        self.assertIsNot(result, records[0])

        result["profile"]["skills"][1]["level"] = 99
        result["profile"]["skills"].append("Rust")
        self.assertEqual(
            records,
            [{"name": "Ada", "profile": {"skills": ["Python", {"level": 5}]}}],
        )

    def test_no_match_and_empty_iterable(self):
        self.assertIsNone(find_record([], "nobody"))
        self.assertIsNone(find_record([{"name": "Ada"}], "Grace"))

    def test_consumes_iterable_once_without_mutation(self):
        underlying = [{"name": "Ada"}, {"name": "Grace"}]
        records = SingleUseRecords(underlying)
        self.assertEqual(find_record(records, "grace"), {"name": "Grace"})
        self.assertEqual(records.iterations, 1)
        self.assertEqual(underlying, [{"name": "Ada"}, {"name": "Grace"}])

    def test_invalid_query(self):
        for query in [None, 3, True, b"Ada"]:
            with self.subTest(query=query):
                with self.assertRaises(TypeError):
                    find_record([], query)
        for query in ["", "   ", "\t\n"]:
            with self.subTest(query=query):
                with self.assertRaises(ValueError):
                    find_record([], query)

    def test_non_iterable_records(self):
        for records in [None, 42, True]:
            with self.subTest(records=records):
                with self.assertRaises(TypeError):
                    find_record(records, "Ada")

    def test_malformed_record_types_and_names(self):
        for records in [["Ada"], [42], [["name", "Ada"]]]:
            with self.subTest(records=records):
                with self.assertRaises(TypeError):
                    find_record(records, "Ada")
        with self.assertRaises(ValueError):
            find_record([{"id": 1}], "Ada")
        for name in [None, 3, True, b"Ada"]:
            with self.subTest(name=name):
                with self.assertRaises(TypeError):
                    find_record([{"name": name}], "Ada")


if __name__ == "__main__":
    unittest.main()

